body.query:
query ParticipantDetails($key: ID!) {
  participant(key: $key) {
    ...ParticipantDetails
    node {
      ...NodeDetails
    }
  }
}

fragment ParticipantDetails on Participant {
  id
  type
  countryCode
  title: name
  gbifRegion
  participationStatus
  membershipStart
  nodeEstablishmentDate
  participantUrl
  rssFeeds {
    label
    url
  }
  newsletters {
    label
    url
  }
  linksToSocialMedia {
    label
    url
  }
}

fragment NodeDetails on Node {
  key
  title
  homepage
  contacts {
    key
    title
    type
    firstName
    surname
    lastName
    institutionName
    email
    phone
    homepage
    organization
    position
    roles
    userId
    address
    city
    postalCode
    province
    country
  }
  dataset(limit: 0) {
    count
  }
  publisher: organization(limit: 0) {
    count
  }
  headOfDelegation: contacts(type: "HEAD_OF_DELEGATION") {
    key
    firstName
    lastName
  }
  participantNodeManager: contacts(type: "NODE_MANAGER") {
    key
    firstName
    lastName
  }
}
